"""Generate the ESP32 allowlist from the same profiles as the PC application."""
from pathlib import Path
import sys


def generate(output: Path) -> None:
    from app.catalog import MCZ_FREQUENCY_HZ, REMOTE_ID, load_command_presets

    rows = []
    for key, frame in sorted(load_command_presets().items()):
        octets = ", ".join(f"0x{byte:02X}" for byte in bytes.fromhex(frame))
        rows.append(f'    {{"{key}", "{frame}", {{{octets}}}}},')
    content = "\n".join([
        "// Generated by tools/build_profiles.py from validated captures; do not edit.",
        "#pragma once",
        '#include "mcz_api.h"',
        f"constexpr uint32_t MCZ_FREQUENCY_HZ = {MCZ_FREQUENCY_HZ};",
        f"constexpr uint32_t MCZ_REMOTE_ID = 0x{REMOTE_ID.hex().upper()};",
        "constexpr MczProfile MCZ_PROFILES[] = {",
        *rows,
        "};",
        "",
    ])
    output.parent.mkdir(parents=True, exist_ok=True)
    if not output.exists() or output.read_text(encoding="utf-8") != content:
        output.write_text(content, encoding="utf-8")


if "Import" not in globals():
    sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
    generate(Path(sys.argv[1]))
else:
    Import("env")
    sys.path.insert(0, env.subst("$PROJECT_DIR"))
    header = Path(env.subst("$BUILD_DIR")) / "generated/mcz_profiles.h"
    generate(header)
    env.Append(CPPPATH=[str(header.parent.resolve())])
